-- 64 Storming the Gate: the catapult lobs a stone at each target in turn.
-- A knight is a skeleton with a `ragdoll`: when a stone reaches one, it goes
-- limp (Ragdoll.set) and takes the stone's push. The bridge's planks hang on
-- hinges with a `break_force`; the stones snap them by physics alone, and
-- each plank's script hears `on_joint_break`. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/64-storming-the-gate.scene"
local MUZZLE_X, MUZZLE_Y = -530, -200
local G = 981
local captions = true
local knights = {}
local balls = {}
local order = { "KnightC", "Plank4", "KnightA", "Plank6", "KnightB" }
local shot, timer, done_t = 0, 1.2, nil
local snaps = 0
local barrel, dust, status

function init(entity)
    barrel = Entity.find_by_name("Barrel")
    dust = Entity.find_by_name("Dust")
    status = Entity.find_by_name("Status")
    for _, name in ipairs({ "KnightA", "KnightB", "KnightC" }) do
        knights[name] = { root = Entity.find_by_name(name), spine = Entity.find_by_name(name .. "Spine"), down = false }
    end
    Event.on("plank_snapped", entity)
end

function on_plank_snapped(entity, data)
    snaps = snaps + 1
end

local function aim_at(name)
    local e = knights[name] and knights[name].spine or Entity.find_by_name(name)
    if not e then return nil end
    local x, y = Transform.get_world_position(e)
    return x, y
end

local function fire()
    shot = shot + 1
    local target = order[(shot - 1) % #order + 1]
    local tx, ty = aim_at(target)
    if not tx then return end
    -- A lob that lands on the target in T seconds.
    local T = 1.15
    local vx = (tx - MUZZLE_X) / T
    local vy = (ty - MUZZLE_Y) / T + 0.5 * G * T
    local b = Entity.spawn_prefab("SbBall")
    Transform.set_position(b, MUZZLE_X, MUZZLE_Y)
    Physics.set_velocity(b, vx, vy)
    balls[#balls + 1] = b
    if barrel then Transform.set_rotation(barrel, (math.atan2 and math.atan2(vy, vx) or math.atan(vy, vx))) end
    if dust then
        Transform.set_position(dust, MUZZLE_X, MUZZLE_Y)
        Particles.emit_burst(dust, 18)
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("R") then Scene.load(SCENE) return end
    if Input.is_key_just_pressed("Space") then fire(); timer = 2.2 end
    timer = timer - dt
    if timer <= 0 then fire(); timer = 2.2 end

    -- A stone that reaches a standing knight knocks it down, the way it flew.
    local standing = 0
    for _, k in pairs(knights) do
        if not k.down and k.spine then
            standing = standing + 1
            local kx, ky = Transform.get_world_position(k.spine)
            for _, b in ipairs(balls) do
                local bx, by = Transform.get_position(b)
                if bx and (bx - kx) ^ 2 + (by - ky) ^ 2 < 55 * 55 then
                    k.down = true
                    Ragdoll.set(k.root, "active", true)
                    local vx, vy = Physics.get_velocity(b)
                    Physics.apply_impulse(k.spine, (vx or 0) * 0.3, (vy or 0) * 0.3 + 120)
                    if dust then
                        Transform.set_position(dust, kx, ky)
                        Particles.emit_burst(dust, 24)
                    end
                    break
                end
            end
        end
    end
    -- All down and the bridge in the moat: begin again.
    if standing == 0 and snaps > 0 then
        done_t = (done_t or 0) + dt
        if done_t > 4 then Scene.load(SCENE) return end
    end
    if status then
        UI.set_text(status, "knights standing " .. standing .. "   bridge ropes snapped " .. snaps)
    end
end
